export default function MuscleMapThumb({
  group,
  size = 56,
  mutedColor = DEFAULT_MUTED,
  highlightColor = DEFAULT_HIGHLIGHT,
}: Props) {
  const { theme } = usePreferences();
  const height = Math.round(size * (VIEWBOX_HEIGHT / VIEWBOX_WIDTH));
  const frameBorder = theme === 'dark' ? '#64748b' : '#0f172a';
  const frameBackground = theme === 'dark' ? '#0b1220' : '#ffffff';
  const mutedOpacity = 0.1;
  const highlightOpacity = 0.65;

  // Map muscle groups to their relevant SVG path IDs
  const getRelevantPaths = (muscleGroup: MuscleGroup): string[] => {
    const pathMap: Record<MuscleGroup, string[]> = {
      'Chest': ['chest_left', 'chest_right'],
      'Back': ['back_left', 'back_right'],
      'Shoulders': ['shoulder_left', 'shoulder_right'],
      'Biceps': ['arms_left', 'arms_right'],
      'Triceps': ['arms_left','arms_right'],
      'Core / Abs': ['abs_upper_left', 'abs_upper_right', 'abs_middle_left', 'abs_middle_right', 'abs_bottom_left', 'abs_bottom_right'],
      'Legs (Quads focus)': ['leg_left', 'leg_right'],
      'Hamstrings / Glutes': ['glutes_left', 'glutes_right'],
      'Calves': ['calves_left', 'calves_right'],
    };
    return pathMap[muscleGroup] || [];
  };

  const activePaths = getRelevantPaths(group);
  const renderPaths = { ...numberedPaths, ...anatomyPathsWithTransforms, ...correctedAbsPaths };

  return (
    <View
      style={[
        styles.wrap,
        {
          width: size,
          height,
          borderColor: frameBorder,
          backgroundColor: frameBackground,
        },
      ]}
    >
      <Svg
        width={size}
        height={height}
        viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
        preserveAspectRatio="xMidYMid meet"
      >
        {/* Body background */}
        <Path d={renderPaths.body_bg.d} fill={renderPaths.body_bg.fill ?? '#fafafa'} />

        {/* Render all paths with appropriate opacity */}
        {Object.entries(renderPaths).map(([pathId, pathInfo]) => {
          if (pathId === 'body_bg') return null;
          const isActive = activePaths.includes(pathId);
          return (
            <G key={pathId} transform={pathInfo.transform}>
              <Path
                d={pathInfo.d}
                fill={isActive ? highlightColor : mutedColor}
                opacity={isActive ? highlightOpacity : mutedOpacity}
              />
            </G>
          );
        })}
      </Svg>
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: {
    overflow: 'hidden',
    borderRadius: 8,
    borderWidth: 1,
  },
});
